solution:
#include <stdio.h>

int tong_den(int n) {
    int tong = 0;
    for (int i = 1; i <= n; i++)
        tong += i;
    return tong;
}

int main(void) {
    int n;
    scanf("%d", &n);
    printf("%d\n", tong_den(n));
    return 0;
}
